import{_ as a,o as i,c as t,a9 as n}from"./chunks/framework.asyjyako.js";const h=JSON.parse('{"title":"Qualified collections","description":"","frontmatter":{},"headers":[],"relativePath":"reference/qualification.md","filePath":"reference/qualification.md","lastUpdated":null}'),o={name:"reference/qualification.md"};function l(s,e,c,r,d,u){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="Qualified-collections" tabindex="-1">Qualified collections <a class="header-anchor" href="#Qualified-collections" aria-label="Permalink to &quot;Qualified collections {#Qualified-collections}&quot;">​</a></h1><p>A PerfChecker release is used with interface packages, Julia versions and external tools. <code>PerfCheckerQualification</code> checks an explicit candidate collection; one passing test cannot cover every combination.</p><h2 id="What-runs-after-a-change" tabindex="-1">What runs after a change <a class="header-anchor" href="#What-runs-after-a-change" aria-label="Permalink to &quot;What runs after a change {#What-runs-after-a-change}&quot;">​</a></h2><ul><li><p>Routine CI checks changed interfaces and their consumers with current dependencies on Linux.</p></li><li><p>Core changes also check Windows and the minimum supported Julia version.</p></li><li><p>Shared contracts and style checks accompany the selected components.</p></li><li><p>Core, contract and unknown-path changes conservatively select every component.</p></li><li><p>The extended Windows/Linux matrix runs weekly or on request with <code>full</code>, adding older dependency combinations and broader platform coverage.</p></li></ul><p>Only the extended matrix can qualify a release. Passing routine CI is not a substitute. Each lane records its runtime and resolved dependency environment.</p><h2 id="Candidate-versus-qualified" tabindex="-1">Candidate versus qualified <a class="header-anchor" href="#Candidate-versus-qualified" aria-label="Permalink to &quot;Candidate versus qualified {#Candidate-versus-qualified}&quot;">​</a></h2><ul><li><p><code>qualification/collection.toml</code> selects candidates.</p></li><li><p>External repositories use full commit SHAs; mutable branches are rejected.</p></li><li><p>A dependency-update PR proposes a new candidate and triggers qualification. Until it passes, the last qualified collection stays the published reference.</p></li></ul><p>Each attempt has its own campaign ID. Missing jobs cannot be filled with reports from an earlier attempt, even at the same revision. Failed, cancelled, skipped, duplicate or mismatched records prevent full qualification.</p><p>The resulting inventory identifies the exact package versions and environment fingerprints per lane — several environments, no single shared Manifest.</p><h2 id="Documentation-publication" tabindex="-1">Documentation publication <a class="header-anchor" href="#Documentation-publication" aria-label="Permalink to &quot;Documentation publication {#Documentation-publication}&quot;">​</a></h2><ul><li><p>Documentation publication is independent of qualification.</p></li><li><p>The <code>Documentation</code> workflow installs documentation dependencies, builds Documenter and VitePress, and publishes <code>/PerfChecker/dev/</code>. No package matrix, browser tests or benchmarks.</p></li><li><p>The extended qualification produces a <code>qualified-collection</code> artifact with the exact tested revisions and environments.</p></li><li><p>Only a complete successful qualification authorizes a package release.</p></li></ul><p>Publishing development documentation does not certify the packages it describes. Pull requests build but cannot publish.</p><h2 id="Limits" tabindex="-1">Limits <a class="header-anchor" href="#Limits" aria-label="Permalink to &quot;Limits {#Limits}&quot;">​</a></h2><ul><li><p>The initial supported platforms are Windows and Linux.</p></li><li><p>Jobs run sequentially: one Julia compute thread, single-thread BLAS, four-thread budget.</p></li><li><p>No measurement is validated merely because a tool executable was found.</p></li></ul><p><a id="What-is-tested-after-a-change"></a></p>',15)])])}const f=a(o,[["render",l]]);export{h as __pageData,f as default};
